#include <queue>

class Solution {
public:
    int deepestLeavesSum(TreeNode* root) {
        std::queue<TreeNode*> q;
        q.push(root);
        int levelSum = 0;
        while (!q.empty()) {
            levelSum = 0;
            int sz = q.size();
            for (int i = 0; i < sz; ++i) {
                TreeNode* node = q.front();
                q.pop();
                levelSum += node->val;
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
        }
        return levelSum;
    }
};

import java.util.*;

class Solution {
    public int deepestLeavesSum(TreeNode root) {
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        int levelSum = 0;
        while (!q.isEmpty()) {
            levelSum = 0;
            int sz = q.size();
            for (int i = 0; i < sz; i++) {
                TreeNode node = q.poll();
                levelSum += node.val;
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
        }
        return levelSum;
    }
}

var deepestLeavesSum = function(root) {
    let q = [root];
    let levelSum = 0;
    while (q.length > 0) {
        levelSum = 0;
        const nextQ = [];
        for (const node of q) {
            levelSum += node.val;
            if (node.left) nextQ.push(node.left);
            if (node.right) nextQ.push(node.right);
        }
        q = nextQ;
    }
    return levelSum;
};
